import itertools

v = 13
k = 4
lam = 3

def get_diffs(block):
    diffs = []
    for i in range(k):
        for j in range(k):
            if i != j:
                diffs.append((block[i] - block[j]) % v)
    return diffs

blocks = list(itertools.combinations(range(v), k))

for b1 in blocks:
    if b1[0] != 0: continue
    for b2 in blocks:
        if b2[0] != 0: continue
        for b3 in blocks:
            if b3[0] != 0: continue

            diffs = get_diffs(b1) + get_diffs(b2) + get_diffs(b3)
            counts = [diffs.count(i) for i in range(1, v)]
            if all(c == lam for c in counts):
                print("Found base blocks:", b1, b2, b3)
                exit(0)

v = 13
b = 39
matrix = [[0]*b for _ in range(v)]

b1 = (0, 1, 2, 5)
b2 = (0, 1, 3, 8)
b3 = (0, 2, 6, 9)

for j in range(13):
    for p in b1:
        matrix[(p+j)%13][j] = 1

for j in range(13):
    for p in b2:
        matrix[(p+j)%13][13+j] = 1

for j in range(13):
    for p in b3:
        matrix[(p+j)%13][26+j] = 1

# Verify
valid = True
for row in matrix:
    if sum(row) != 12:
        valid = False
        print("Row sum error")

for j in range(b):
    col_sum = sum(matrix[i][j] for i in range(v))
    if col_sum != 4:
        valid = False
        print("Col sum error")

for i1 in range(v):
    for i2 in range(i1+1, v):
        dot = sum(matrix[i1][j]*matrix[i2][j] for j in range(b))
        if dot != 3:
            valid = False
            print(f"Dot product error {i1} {i2}: {dot}")

if valid:
    print("Valid!")
    flat = [x for row in matrix for x in row]
    print(flat)
